clc;
close all;
clear all;
s1 = [1 2 3 4 0 0 0 0 0];
n = 0:length(s1)-1;
k = 2;
s2 = [zeros(1,k) s1(1:end-k)];
y11 = s2;
y1 = s1;
y11_shift = [zeros(1,k) y1(1:end-k)];
tol = 0.0001;
if (sum(abs(y11-y11_shift)) < tol) %[output:group:58b55dd3]
    disp("System Is Time Invariant"); %[output:1d948de2]
else
    disp("System Is Time Variant");
end %[output:group:58b55dd3]
n_out1 = 0:length(y11)-1;
n_out2 = 0:length(y11_shift)-1;
figure(1); %[output:28364d38]
stem(n_out1,y11); %[output:28364d38]
xlabel("Sample"); %[output:28364d38]
ylabel("Amplitude"); %[output:28364d38]
title("Time Invariant Test"); %[output:28364d38]
figure(2); %[output:6d5c30e5]
stem(n_out2,y11_shift); %[output:6d5c30e5]
xlabel("Sample"); %[output:6d5c30e5]
ylabel("Amplitude"); %[output:6d5c30e5]
title("Time Invariant Test"); %[output:6d5c30e5]


